<?phpclass M_users_notification extends CI_Model {	public $_table_name = 'notification';	function __construst() {		parent::__construst();	}	private function generate_select() {        return $this->_table_name . '.*, actor.full_name as actor_full_name, actor.photo as actor_photo, notifier.full_name as notifier_full_name';    }    private function generate_from() {        $this->db->from($this->_table_name);        $this->db->join('users as actor', 'actor.userid = ' . $this->_table_name . '.actor_id', 'left');        $this->db->join('users as notifier', 'notifier.userid = ' . $this->_table_name . '.notifier_id', 'left');    }    private function generate_where($args) {		if (isset($args['q'])) {            $this->db->group_start();            $this->db->like("actor.full_name", $args['q']);            $this->db->or_like("notifier.full_name", $args['q']);            $this->db->group_end();        }        if (isset($args['id'])) {            $this->db->where($this->_table_name . ".id", $args['id']);        }		if (isset($args['in_id'])) {            $this->db->where_in($this->_table_name . ".id", $args['in_id']);        }		if (isset($args['not_in_id'])) {            $this->db->where_not_in($this->_table_name . ".id", $args['not_in_id']);        }		if (isset($args['in_actor_id'])) {            $this->db->where_in($this->_table_name . ".actor_id", $args['in_actor_id']);        }		if (isset($args['actor_id'])) {            $this->db->where($this->_table_name . ".actor_id", $args['actor_id']);        }        if (isset($args['in_notifier_id'])) {            $this->db->where_in($this->_table_name . ".notifier_id", $args['in_notifier_id']);        }        if (isset($args['notifier_id'])) {            $this->db->where($this->_table_name . ".notifier_id", $args['notifier_id']);        }        if (isset($args['status'])) {            $this->db->where($this->_table_name . ".status", $args['status']);        }        if (isset($args['action'])) {            $this->db->where($this->_table_name . ".action", $args['action']);        }        if (isset($args['in_action'])) {            $this->db->where_in($this->_table_name . ".action", $args['in_action']);        }        if (isset($args['start_date_start'])) {            $this->db->where($this->_table_name . ".created >=", $args['start_date_start']);        }        if (isset($args['start_date_end'])) {            $this->db->where($this->_table_name . ".created <=", $args['start_date_end']);        }    }    private function generate_order_by($args) {        $allow_sort = array("DESC", "ASC");        if (isset($args['order_by']) && is_array($args['order_by']) && !empty($args['order_by'])) {            foreach ($args['order_by'] as $key => $value) {                $sort = in_array($value, $allow_sort) ? $value : "DESC";                $this->db->order_by($this->_table_name . '.' . $key, $sort);            }        }    }    function default_args() {        $order_by = array(            'status' => 'ASC',            'created' => 'DESC',        );        $args = array();        $args['order_by'] = $order_by;        return $args;    }    function gets($options = array(), $perpage = 5, $offset = -1) {        $default_args = $this->default_args();        if (is_array($options) && !empty($options)) {            $args = array_merge($default_args, $options);        } else {            $args = $default_args;        }        $this->db->select($this->generate_select());        $this->db->from($this->_table_name);        $this->db->join('users as actor', 'actor.userid = ' . $this->_table_name . '.actor_id', 'left');        $this->db->join('users as notifier', 'notifier.userid = ' . $this->_table_name . '.notifier_id', 'left');        $this->generate_where($args);        $this->generate_order_by($args);        if ($offset >= 0) {            $this->db->limit($perpage, $offset);        }        $query = $this->db->get();        return $query->result_array();    }    function counts($options = array()) {        $default_args = $this->default_args();        if (is_array($options) && !empty($options)) {            $args = array_merge($default_args, $options);        } else {            $args = $default_args;        }        $this->db->select();        $this->db->from($this->_table_name);        $this->db->join('users as actor', 'actor.userid = ' . $this->_table_name . '.actor_id', 'left');        $this->db->join('users as notifier', 'notifier.userid = ' . $this->_table_name . '.notifier_id', 'left');        $this->generate_where($args);        $query = $this->db->get();        return $query->num_rows();    }    function get($id = 0) {        $this->db->select($this->generate_select());        $this->db->from($this->_table_name);        $this->db->join('users as actor', 'actor.userid = ' . $this->_table_name . '.actor_id', 'left');        $this->db->join('users as notifier', 'notifier.userid = ' . $this->_table_name . '.notifier_id', 'left');        $this->db->where($this->_table_name . '.id', $id);        $query = $this->db->get();        return $query->row_array();    }    function get_by($args) {        $this->db->select($this->generate_select());        $this->db->from($this->_table_name);        $this->db->join('users as actor', 'actor.userid = ' . $this->_table_name . '.actor_id', 'left');        $this->db->join('users as notifier', 'notifier.userid = ' . $this->_table_name . '.notifier_id', 'left');        $this->generate_where($args);        $query = $this->db->get();        return $query->row_array();    }    function add($data = array()) {        if (empty($data)) {            return 0;        }        $query = $this->db->insert($this->_table_name, $data);        $insert_id = $this->db->insert_id();        return isset($query) ? $insert_id : 0;    }    function update($args, $data) {        if (empty($args) || empty($data)) {            return false;        }        $this->generate_where($args);        $query = $this->db->update($this->_table_name, $data);        return isset($query) ? true : false;    }    function delete($args) {        if (empty($args)) {            return false;        }        $this->generate_where($args);        $query = $this->db->delete($this->_table_name);        return isset($query) ? true : false;    }}/* End of file M_users_notification.php *//* Location: ./application/modules/users/models/M_users_notification.php */